class Solution {
    public int timeRequiredToBuy(int[] tickets, int k) {
        int target = tickets[k];
        int time = 0;
        for (int i = 0; i < tickets.length; i++) {
            int cap = i <= k ? target : target - 1;
            time += Math.min(tickets[i], cap);
        }
        return time;
    }
}

class Solution {
    public int timeRequiredToBuy(int[] tickets, int k) {
        int target = tickets[k];
        int time = 0;
        for (int i = 0; i <= k; i++) {
            time += Math.min(tickets[i], target);
        }
        for (int i = k + 1; i < tickets.length; i++) {
            time += Math.min(tickets[i], target - 1);
        }
        return time;
    }
}

import java.util.ArrayDeque;
import java.util.Queue;

class Solution {
    public int timeRequiredToBuy(int[] tickets, int k) {
        Queue<Integer> queue = new ArrayDeque<>();
        for (int i = 0; i < tickets.length; i++) {
            queue.offer(i);
        }
        int[] remaining = tickets.clone();
        int time = 0;
        while (true) {
            int index = queue.poll();
            remaining[index]--;
            time++;
            if (index == k && remaining[index] == 0) {
                return time;
            }
            if (remaining[index] > 0) {
                queue.offer(index);
            }
        }
    }
}

class Solution {
    public int timeRequiredToBuy(int[] tickets, int k) {
        int[] remaining = tickets.clone();
        int time = 0;
        while (true) {
            for (int i = 0; i < remaining.length; i++) {
                if (remaining[i] == 0) {
                    continue;
                }
                remaining[i]--;
                time++;
                if (i == k && remaining[i] == 0) {
                    return time;
                }
            }
        }
    }
}

class Solution {
    public int timeRequiredToBuy(int[] tickets, int k) {
        int target = tickets[k];
        int time = 0;
        for (int round = 1; round <= target; round++) {
            for (int i = 0; i < tickets.length; i++) {
                if (tickets[i] >= round && (round < target || i <= k)) {
                    time++;
                }
            }
        }
        return time;
    }
}
